<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/intl-tel-input@27.1.3/dist/css/intlTelInput.css" defer>
<script src="https://cdn.jsdelivr.net/npm/intl-tel-input@27.1.3/dist/js/intlTelInput.min.js"></script>

<style>
    .iti { width: 100%; } .iti__selected-dial-code { color: white; } .iti__country-name { color: black; text-align: left }
</style>
{ignore}
<script>
    const inputs = document.querySelectorAll("[data-type-phone]");
    for (const input of inputs) {
        window.intlTelInput(input, {
            utilsScript: "https://cdn.jsdelivr.net/npm/intl-tel-input@27.1.3/dist/js/utils.js",
            initialCountry: "ru",
            separateDialCode: true,
            nationalMode: false,
            formatOnDisplay: true,
            formatOnType: true,
            autoFormat: true,
            preferredCountries: ["ru"],
        });
    }
</script>
{/ignore}',
